 float gl=0,gr=0,weight=0;foreach(var v in voices)if(v.Age<v.Length){float w=GrainWindow[(int)((long)v.Age*2047/v.Length)];gl+=GrainRead(historyL,v.Position,v.Band)*w;gr+=GrainRead(historyR,v.Position,v.Band)*w;weight+=w;v.Age++;v.Position+=v.Rate;}if(!Freeze)historyAt=(historyAt+1)%historyL.Length;float norm=1/Math.Max(1,weight);float cl=0,cr=0;cloudBlend+=((GrainMode==0?0:1)-cloudBlend)*.003f;if(GrainMode!=0||cloudBlend>.00001f)cloud.Process(l,r,this,out cl,out cr);gl=gl*norm*(1-cloudBlend)+cl*cloudBlend;gr=gr*norm*(1-cloudBlend)+cr*cloudBlend;mixSmooth+=(Math.Max(0,Math.Min(1,GrainMix))-mixSmooth)*.003f;if(Math.Abs(GrainMix-mixSmooth)<.00005f)mixSmooth=Math.Max(0,Math.Min(1,GrainMix));float amount=gs<.00005f?0:gs>.99995f?1:gs;float dry=1+(Math.Min(1,2*(1-mixSmooth))-1)*amount,wet=Math.Min(1,2*mixSmooth);float postTarget=Routing==0?0:1,chainTarget=Routing==1?1:0;postBlend+=(postTarget-postBlend)*.003f;serialBlend+=(chainTarget-serialBlend)*.003f;if(Math.Abs(postTarget-postBlend)<.00005f)postBlend=postTarget;if(Math.Abs(chainTarget-serialBlend)<.00005f)serialBlend=chainTarget;
