 float reL,reR,rl=0,rr=0;roomBlend+=((ReverbMode==1?1:0)-roomBlend)*.003f;hall.Tone=room.Tone=HallTone;float hl=(stageL+dl*.5f*serialBlend)*rs,hr=(stageR+dr*.5f*serialBlend)*rs;hall.Process(hl,hr,Size,out reL,out reR);if(ReverbMode==1||roomBlend>.00001f){room.Process(hl,hr,Size,out rl,out rr);roomActive=true;}else if(roomActive){room.Clear();roomActive=false;}reL+=(rl-reL)*roomBlend;reR+=(rr-reR)*roomBlend;
wetL=(reL+dl*.5f+gl*gs*wet+l*(dry-1))*resetGate;wetR=(reR+dr*.5f+gr*gs*wet+r*(dry-1))*resetGate;}
 internal void SnapRouting(){postBlend=Routing==0?0:1;serialBlend=Routing==1?1:0;}
 public void ResetDefaults(){ReverbMode=DelayMode=0;Routing=1;Reverb=Delay=Grain=Filter=GrainPitch=0;Size=HallTone=GrainMix=.5f;Time=.375f;Feedback=.35f;GrainSize=.09f;Spray=.3f;GrainMode=0;CloudFeedback=.45f;Cloudy=Texture=.65f;CloudWindow=.25f;Spread=.75f;CloudLoFi=Freeze=GrainReverse=false;DelaySync=true;Division=2;Feel=1;Density=4;Position=.15f;resetRequested=true;}
